/**
 * Keep generated prose consistent with the published probe reference.
 * This rendering check does not replace the publisher's original-source replay.
 *
 * @param document - Validated full inventory or its streaming projection.
 */
export const phpWasmRefinementEntryReference = document => {
	const references = document.evidence.filter(item => item.id === phpWasmEntryProbeEvidenceId);
	if(references.length === 0) return phpWasmRefinementEntryBoundary;
	assert.equal(references.length, 1, "Exactly one hosted probe reference");
	for(const observation of document.observations)
		for(const stage of Object.values(observation.stages))
			assert.ok(!stage.evidence.includes(phpWasmEntryProbeEvidenceId)
				, "Entry probes cannot establish prepared-package support");
	return renderPhpWasmEntryProbeBoundary(references[0]);
};

import { phpWasmRefinementEntryReference } from "../../scripts/generate-type-docs.mjs";
import { phpWasmEntryProbeEvidenceId } from "./php-wasm-refinement-entry-publication.mjs";
import {
	phpWasmEntryProbeDocumentationPaths, phpWasmEntryProbePreviousDocumentation
	, renderPhpWasmEntryProbeBoundary
} from "./php-wasm-refinement-entry-publication-docs.mjs";
import { readPromotionInventory } from "./type-surface-promotion-io.mjs";

let inventory;
const readInventory = () => inventory ??= (async () => {
	const irSchema = JSON.parse(await readFile("schema/binding-ir.schema.json", "utf8"));
	const consumers = JSON.parse(await readFile("docs/consumer-support.v1.json", "utf8"));
	return (await readPromotionInventory(createReadStream("docs/type-surface.v1.json")
		, { irSchema, consumers }, { retainEvidence: [evidenceId] })).document;
})();

const document = await readInventory();
phpWasmRefinementEntryReference(document);
const hosted = document.evidence.find(item => item.id === phpWasmEntryProbeEvidenceId);

const name = Object.keys(phpWasmEntryProbeDocumentationPaths)
	.find(name => phpWasmEntryProbeDocumentationPaths[name] === page.path);
if(hosted)
{
	assert.ok(source.includes(renderPhpWasmEntryProbeBoundary(hosted, name)), page.path);
	assert.ok(!source.includes(phpWasmEntryProbePreviousDocumentation[name]), page.path);
}
else
	assert.match(source
		, /no hosted (?:entry-)?count claim|not\s+a\s+hosted\s+result|not[^.]*hosted evidence/iu
		, page.path);

test("promotion inventory retains only explicitly selected complete evidence", async () => {
	const value = fixture();
	const result = await read(value, { retainEvidence: ["second"] });
	assert.equal(result.document.evidence[0].files.length, 1);
	assert.deepEqual(result.document.evidence[1], value.evidence[1]);
	for(const retainEvidence of [null, "second", ["missing"], ["second", "second"]
		, [""], [1], Array.from({ length: 9 }, (_, index) => String(index))])
		await assert.rejects(read(value, { retainEvidence }));
	value.evidence[1].files[1].sha256 = "invalid";
	await assert.rejects(read(value, { retainEvidence: ["second"] }));
});

assert.ok(Array.isArray(retainEvidence) && retainEvidence.length <= 8);
assert.ok(retainEvidence.every(id => typeof id === "string" && id.length > 0));
const retained = new Set(retainEvidence);
assert.equal(retained.size, retainEvidence.length, "Unique retained evidence IDs");
